import mongoose, { Schema, model, models } from "mongoose";

/**
 * URL Schema Definition
 * 
 * This defines the structure of documents stored in MongoDB
 * Mongoose uses schemas to enforce data types and validation
 * 
 * Fields:
 * - longUrl: The original long URL that users want to shorten
 * - shortCode: The unique 7-character code generated by nanoid (e.g., "a3b9k2m")
 * - clicks: Counter tracking how many times the short link was accessed
 * - createdAt: Timestamp automatically set when document is created
 * 
 * Indexes:
 * - shortCode is indexed for fast lookups (we'll query by this often)
 * - Indexes make database queries much faster
 */

interface IURL {
  longUrl: string;
  shortCode: string;
  clicks: number;
  createdAt: Date;
}

const urlSchema = new Schema<IURL>(
  {
    longUrl: {
      type: String,
      required: [true, "Long URL is required"],
      trim: true,
    },
    shortCode: {
      type: String,
      required: true,
      unique: true, // Ensures no duplicate short codes
      trim: true,
      index: true, // Creates an index for faster queries
    },
    clicks: {
      type: Number,
      default: 0, // Start at 0 clicks
      min: 0, // Can't have negative clicks
    },
    createdAt: {
      type: Date,
      default: Date.now, // Automatically set to current time
    },
  },
  {
    // Automatically manage createdAt/updatedAt timestamps
    // Mongoose will update updatedAt on every save
    timestamps: false, // We only want createdAt, so we manage it manually
  }
);

// Use models.URL if it exists (for hot reloading in dev), otherwise create new model
// This prevents "Cannot overwrite model" errors during development
const URL = models.URL || model<IURL>("URL", urlSchema);

export default URL;
